// The HTTP-shaped API: a pure function of a store and a request -- { method, path, body } -> { status, body }.
import { formatted } from "./money.mjs";
import { cancelOrder, createOrder, getOrder, invalidOf, shipOrder } from "./orders.mjs";

const viewOf = (order) => ({ ...order, total: formatted(order.totalMinor, order.currency) });

const ANSWERS = [
  { when: (r) => !r || r.error === "NOT_FOUND", answer: () => ({ status: 404, body: { error: "no such order" } }) },
  { when: (r) => r.error === "CONFLICT", answer: (r) => ({ status: 409, body: { error: `the order is ${r.state}` } }) },
  { when: () => true, answer: (r, ok) => ({ status: ok, body: viewOf(r) }) },
];

const answered = (r, ok = 200) => ANSWERS.find((a) => a.when(r)).answer(r, ok);

const created = (store, body) => ((why) => (why ? { status: 400, body: { error: `invalid ${why}` } } : answered(createOrder(store, body), 201)))(invalidOf(body));

const ORDER = "(ord-\\d{4})";

export const ROUTES = [
  { method: "POST", path: new RegExp("^/orders$"), run: (store, m, body) => created(store, body ?? {}) },
  { method: "GET", path: new RegExp(`^/orders/${ORDER}$`), run: (store, m) => answered(getOrder(store, m[1])) },
  { method: "POST", path: new RegExp(`^/orders/${ORDER}/ship$`), run: (store, m) => answered(shipOrder(store, m[1])) },
  { method: "POST", path: new RegExp(`^/orders/${ORDER}/cancel$`), run: (store, m) => answered(cancelOrder(store, m[1])) },
];

export function handle(store, request) {
  const route = ROUTES.find((r) => r.method === request?.method && r.path.test(String(request?.path ?? "")));
  return route ? route.run(store, route.path.exec(request.path), request.body) : { status: 404, body: { error: "no such route" } };
}

// Money in minor units (cents for USD and EUR, yen for JPY): a line's total, an order's total after a whole-percentage
// discount, and a total formatted for its currency.
export const CURRENCIES = { USD: { minor: 2, symbol: "$" }, EUR: { minor: 2, symbol: "€" }, JPY: { minor: 0, symbol: "¥" } };

export const lineTotal = (line) => line.qty * line.unitMinor;

export const subtotal = (lines) => lines.reduce((sum, line) => sum + lineTotal(line), 0);

// What a whole-percentage discount leaves of an amount, rounded half up to the minor unit, in integers only.
export const discounted = (minor, percent) => Math.floor((minor * (100 - percent) + 50) / 100);

export const orderTotal = (lines, percent = 0) => discounted(subtotal(lines), percent);

const currencyOf = (code) => CURRENCIES[code] ?? CURRENCIES.USD;

export const formatted = (minor, code = "USD") => ((c) => `${c.symbol}${(minor / 10 ** c.minor).toFixed(c.minor)}`)(currencyOf(code));

// Orders: created open with their total computed once, shipped once, and cancelled only while they are still open.
import { CURRENCIES, orderTotal } from "./money.mjs";

const nextId = (store) => `ord-${String(store.list("orders").length + 1).padStart(4, "0")}`;

const validLine = (l) => Number.isInteger(l?.qty) && l.qty > 0 && Number.isInteger(l?.unitMinor) && l.unitMinor >= 0;

const validPercent = (p) => Number.isInteger(p) && p >= 0 && p <= 100;

// Why an order cannot be made of what was sent, or null.
export const invalidOf = (input) => (!Array.isArray(input?.lines) || !input.lines.length || !input.lines.every(validLine) ? "lines" : !validPercent(input.percent ?? 0) ? "percent" : !Object.hasOwn(CURRENCIES, input.currency ?? "USD") ? "currency" : null);

export function createOrder(store, input) {
  const order = { id: nextId(store), customer: String(input.customer ?? ""), lines: input.lines, percent: input.percent ?? 0, currency: input.currency ?? "USD", note: String(input.note ?? ""), state: "open" };
  return store.put("orders", order.id, { ...order, totalMinor: orderTotal(order.lines, order.percent) });
}

export const getOrder = (store, id) => store.get("orders", id);

function moved(store, id, from, to) {
  const order = getOrder(store, id);
  if (!order) return { error: "NOT_FOUND" };
  return order.state === from ? store.put("orders", id, { ...order, state: to }) : { error: "CONFLICT", state: order.state };
}

export const shipOrder = (store, id) => moved(store, id, "open", "shipped");

export const cancelOrder = (store, id) => moved(store, id, "open", "cancelled");

// The durable store: one JSON file per record, under its kind -- what a process that stops and starts again still finds.
import { existsSync, mkdirSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";

const fileOf = (dir, kind, id) => join(dir, kind, `${id}.json`);

const read = (file) => (existsSync(file) ? JSON.parse(readFileSync(file, "utf8")) : null);

function written(file, record) {
  mkdirSync(dirname(file), { recursive: true });
  writeFileSync(file, `${JSON.stringify(record)}\n`);
  return record;
}

const listed = (dir, kind) => (existsSync(join(dir, kind)) ? readdirSync(join(dir, kind)).filter((n) => n.endsWith(".json")).sort().map((n) => read(join(dir, kind, n))) : []);

export const openStore = (dir) => ({ dir, get: (kind, id) => read(fileOf(dir, kind, id)), put: (kind, id, record) => written(fileOf(dir, kind, id), record), list: (kind) => listed(dir, kind) });

// An order as HTML: every value a customer typed is escaped before it is drawn.
import { formatted } from "./money.mjs";

const ESCAPES = { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" };

export const escaped = (text) => String(text ?? "").replace(/[&<>"']/g, (ch) => ESCAPES[ch]);

const noteOf = (order) => (order.note ? [`  <p class="note">${escaped(order.note)}</p>`] : []);

export const renderOrder = (order) => [`<article class="order" id="${escaped(order.id)}">`, `  <h2>${escaped(order.customer)}</h2>`, `  <p class="total">${escaped(formatted(order.totalMinor, order.currency))}</p>`, `  <p class="state">${escaped(order.state)}</p>`, ...noteOf(order), "</article>"].join("\n");

// The payments consumer: an `order.paid` message writes that order's invoice, and the message is acknowledged only
// once the invoice is written.
import { getOrder } from "./orders.mjs";

const nextInvoice = (store) => `inv-${String(store.list("invoices").length + 1).padStart(4, "0")}`;

function invoiced(store, message, order) {
  const id = nextInvoice(store);
  store.put("invoices", id, { id, orderId: order.id, amountMinor: order.totalMinor, currency: order.currency, messageId: message.id });
  return { ack: true, invoice: id };
}

const paid = (store, message) => ((order) => (order ? invoiced(store, message, order) : { ack: false, error: "no such order" }))(getOrder(store, message.orderId));

export function consume(store, message) {
  if (message?.type !== "order.paid") return { ack: true, skipped: "not a payment" };
  return paid(store, message);
}

import assert from "node:assert/strict";
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { test } from "node:test";
import { handle } from "../src/api.mjs";
import { openStore } from "../src/store.mjs";

function fresh(t) {
  const dir = mkdtempSync(join(tmpdir(), "orders-"));
  t.after(() => rmSync(dir, { recursive: true, force: true }));
  return openStore(dir);
}

const made = (store) => handle(store, { method: "POST", path: "/orders", body: { lines: [{ qty: 1, unitMinor: 700 }] } }).body.id;

test("an open order can be cancelled, and a cancelled order is never shipped", (t) => {
  const store = fresh(t);
  const id = made(store);
  assert.equal(handle(store, { method: "POST", path: `/orders/${id}/cancel` }).body.state, "cancelled");
  assert.equal(handle(store, { method: "POST", path: `/orders/${id}/ship` }).status, 409);
});

test("a shipped order cannot be cancelled", (t) => {
  const store = fresh(t);
  const id = made(store);
  handle(store, { method: "POST", path: `/orders/${id}/ship` });
  assert.equal(handle(store, { method: "POST", path: `/orders/${id}/cancel` }).status, 409);
});

import assert from "node:assert/strict";
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { test } from "node:test";
import { handle } from "../src/api.mjs";
import { openStore } from "../src/store.mjs";

function fresh(t) {
  const dir = mkdtempSync(join(tmpdir(), "orders-"));
  t.after(() => rmSync(dir, { recursive: true, force: true }));
  return openStore(dir);
}

const order = (store, currency) => handle(store, { method: "POST", path: "/orders", body: { lines: [{ qty: 1, unitMinor: 1234 }], currency } });

test("an order keeps its currency, and its total is formatted in it", (t) => {
  const store = fresh(t);
  assert.deepEqual([order(store, "JPY").body.total, order(store, "EUR").body.total], ["¥1234", "€12.34"]);
});

test("a currency nobody keeps is refused", (t) => {
  assert.equal(order(fresh(t), "XXX").status, 400);
});

import assert from "node:assert/strict";
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { test } from "node:test";
import { createOrder } from "../src/orders.mjs";
import { consume } from "../src/worker.mjs";
import { openStore } from "../src/store.mjs";

function fresh(t) {
  const dir = mkdtempSync(join(tmpdir(), "orders-"));
  t.after(() => rmSync(dir, { recursive: true, force: true }));
  return openStore(dir);
}

test("a payment writes the order's invoice, and the invoice is still there when the store is opened again", (t) => {
  const store = fresh(t);
  const order = createOrder(store, { lines: [{ qty: 3, unitMinor: 400 }] });
  assert.equal(consume(store, { id: "m-1", type: "order.paid", orderId: order.id }).ack, true);
  assert.deepEqual(openStore(store.dir).list("invoices").map((i) => [i.orderId, i.amountMinor]), [[order.id, 1200]]);
});

import assert from "node:assert/strict";
import { test } from "node:test";
import { formatted, lineTotal, orderTotal, subtotal } from "../src/money.mjs";

test("a line's total is its quantity times its unit price, in minor units", () => {
  assert.equal(lineTotal({ qty: 3, unitMinor: 250 }), 750);
  assert.equal(subtotal([{ qty: 1, unitMinor: 100 }, { qty: 2, unitMinor: 5 }]), 110);
});

test("an order with no discount costs its subtotal, and a round discount is exact", () => {
  assert.equal(orderTotal([{ qty: 2, unitMinor: 500 }]), 1000);
  assert.equal(orderTotal([{ qty: 2, unitMinor: 500 }], 10), 900);
});

test("a total is formatted in dollars by default", () => {
  assert.equal(formatted(1234), "$12.34");
});

import assert from "node:assert/strict";
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { test } from "node:test";
import { handle } from "../src/api.mjs";
import { openStore } from "../src/store.mjs";
import { renderOrder } from "../src/ui.mjs";

function fresh(t) {
  const dir = mkdtempSync(join(tmpdir(), "orders-"));
  t.after(() => rmSync(dir, { recursive: true, force: true }));
  return openStore(dir);
}

test("an order keeps the note it was created with, and draws it escaped", (t) => {
  const store = fresh(t);
  const id = handle(store, { method: "POST", path: "/orders", body: { lines: [{ qty: 1, unitMinor: 100 }], note: "leave at <door>" } }).body.id;
  const order = handle(store, { method: "GET", path: `/orders/${id}` }).body;
  assert.equal(order.note, "leave at <door>");
  assert.match(renderOrder(order), /<p class="note">leave at &lt;door&gt;<\/p>/);
});

import assert from "node:assert/strict";
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { test } from "node:test";
import { handle } from "../src/api.mjs";
import { openStore } from "../src/store.mjs";

function fresh(t) {
  const dir = mkdtempSync(join(tmpdir(), "orders-"));
  t.after(() => rmSync(dir, { recursive: true, force: true }));
  return openStore(dir);
}

const LINES = [{ qty: 2, unitMinor: 500 }];

test("an order is created open, read back, and shipped once", (t) => {
  const store = fresh(t);
  const made = handle(store, { method: "POST", path: "/orders", body: { customer: "Ada", lines: LINES } });
  assert.deepEqual([made.status, made.body.state, made.body.total], [201, "open", "$10.00"]);
  assert.equal(handle(store, { method: "POST", path: `/orders/${made.body.id}/ship` }).body.state, "shipped");
  assert.equal(handle(store, { method: "POST", path: `/orders/${made.body.id}/ship` }).status, 409);
});

test("an unknown order and an unknown route are 404, and an order with no lines is refused", (t) => {
  const store = fresh(t);
  assert.equal(handle(store, { method: "GET", path: "/orders/ord-0001" }).status, 404);
  assert.equal(handle(store, { method: "DELETE", path: "/orders" }).status, 404);
  assert.equal(handle(store, { method: "POST", path: "/orders", body: { lines: [] } }).status, 400);
});

import assert from "node:assert/strict";
import { test } from "node:test";
import { renderOrder } from "../src/ui.mjs";

test("an order is drawn with its customer escaped, its total and its state", () => {
  const html = renderOrder({ id: "ord-0001", customer: "Ada & <Bob>", totalMinor: 1000, currency: "USD", state: "open", note: "" });
  assert.match(html, /<h2>Ada &amp; &lt;Bob&gt;<\/h2>/);
  assert.match(html, /<p class="total">\$10\.00<\/p>/);
  assert.match(html, /<p class="state">open<\/p>/);
});

import assert from "node:assert/strict";
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { test } from "node:test";
import { consume } from "../src/worker.mjs";
import { openStore } from "../src/store.mjs";

function fresh(t) {
  const dir = mkdtempSync(join(tmpdir(), "orders-"));
  t.after(() => rmSync(dir, { recursive: true, force: true }));
  return openStore(dir);
}

test("a message that is not a payment is acknowledged and skipped", (t) => {
  assert.deepEqual(consume(fresh(t), { id: "m-1", type: "order.shipped", orderId: "ord-0001" }), { ack: true, skipped: "not a payment" });
});

test("a payment for an order nobody has is not acknowledged, so it is delivered again", (t) => {
  assert.equal(consume(fresh(t), { id: "m-1", type: "order.paid", orderId: "ord-0009" }).ack, false);
});
